<script setup>
import { ref, onMounted } from 'vue'
import { useRoute, useRouter } from 'vue-router'
import axios from 'axios'
import { useUserStore } from '@/stores/user'
const route=useRoute(); const router=useRouter(); const userStore=useUserStore(); const API_BASE=import.meta.env.VITE_API_BASE||'/api'
const email=ref(String(route.query.email||userStore.user?.email||'')); const code=ref(''); const status=ref(''); const error=ref(''); const verifying=ref(false); const sending=ref(false)
async function verify(){error.value='';status.value='';if(!email.value||code.value.trim().length!==6){error.value='Informe o e-mail e o código de 6 dígitos.';return}verifying.value=true;try{const r=await axios.post(`${API_BASE}/auth/verify-email`,{email:email.value,code:code.value.trim()});status.value=r.data.message||'E-mail verificado com sucesso!';if(userStore.user?.email===email.value){userStore.user.emailVerificado=true;localStorage.setItem('user',JSON.stringify(userStore.user))}}catch(e){error.value=e.response?.data?.erro||'Código inválido ou expirado.'}finally{verifying.value=false}}
async function resend(){error.value='';status.value='';sending.value=true;try{const r=await axios.post(`${API_BASE}/auth/resend-verification`,{email:email.value});status.value=r.data.message||'Novo código enviado.'}catch(e){error.value=e.response?.data?.erro||'Não foi possível enviar o código.'}finally{sending.value=false}}
onMounted(()=>{if(route.query.token){axios.get(`${API_BASE}/auth/verify-email`,{params:{token:route.query.token,email:route.query.email}}).then(()=>{status.value='E-mail confirmado com sucesso!'}).catch(e=>{error.value=e.response?.data?.erro||'Não foi possível confirmar o e-mail.'})}})
</script>
<template><main class="verify-page"><div class="verify-card"><div class="verify-icon">✉</div><span class="kicker">SEGURANÇA DA CONTA</span><h1>Verifique seu e-mail</h1><p>Enviamos um código de 6 dígitos para confirmar que este e-mail realmente pertence a você.</p><label>E-mail<input v-model="email" type="email" placeholder="seu@email.com"></label><label>Código de verificação<input v-model="code" inputmode="numeric" maxlength="6" placeholder="000000" @keyup.enter="verify"></label><p v-if="error" class="msg error">{{error}}</p><p v-if="status" class="msg success">{{status}}</p><button class="primary" :disabled="verifying" @click="verify">{{verifying?'Verificando...':'Verificar e-mail'}}</button><button class="secondary" :disabled="sending" @click="resend">{{sending?'Enviando...':'Reenviar código'}}</button><button class="back" @click="router.push('/')">Voltar ao início</button></div></main></template>
<style scoped>.verify-page{min-height:calc(100vh - 72px);display:grid;place-items:center;padding:30px;background:var(--color-background)}.verify-card{max-width:470px;width:100%;padding:38px;background:var(--white);border:1px solid var(--line);border-radius:20px;box-shadow:var(--shadow);text-align:center}.verify-icon{width:54px;height:54px;margin:0 auto 12px;border-radius:50%;display:grid;place-items:center;background:var(--green-soft);color:var(--green-dark);font-size:24px}.kicker{font-size:10px;letter-spacing:.14em;font-weight:900;color:var(--green-dark)}.verify-card h1{font-size:26px;color:var(--navy);margin:8px 0}.verify-card>p{font-size:12px;color:var(--muted);line-height:1.65;margin-bottom:20px}.verify-card label{display:block;text-align:left;font-size:10px;font-weight:800;color:var(--muted);margin:12px 0}.verify-card input{display:block;width:100%;box-sizing:border-box;height:42px;margin-top:6px;border:1px solid var(--line);border-radius:9px;background:var(--cream-2);padding:0 12px;color:var(--text);font-size:13px}.verify-card label:nth-of-type(2) input{text-align:center;letter-spacing:.35em;font-size:18px;font-weight:800}.primary,.secondary,.back{width:100%;height:40px;border-radius:9px;font-weight:800;margin-top:8px}.primary{border:0;background:var(--green);color:#fff}.secondary{border:1px solid var(--line);background:var(--cream-2);color:var(--navy)}.back{border:0;background:transparent;color:var(--muted)}.msg{text-align:left!important;padding:9px;border-radius:8px;margin:10px 0!important;font-size:10px!important}.msg.error{background:#fff0f0;color:#a52b2b}.msg.success{background:var(--green-soft);color:var(--green-dark)}</style>
